local UI = { Version = "LunarUI.V10.BlueTranslucent.GetKey" }
local function _ui_member(o, k)
    if o == nil then return nil end
    local ok, v = pcall(function() return o[k] end)
    if ok then return v end
end
local function _ui_valid(o)
    if o == nil then return false end
    local ok, v = pcall(slua.isValid, o)
    return ok and v == true
end
local _ui_vectorClass = rawget(_G, "FVector2D") or import("Vector2D")
local _ui_colorClass = rawget(_G, "FLinearColor") or import("LinearColor")
local function _ui_vector(x, y) return _ui_vectorClass(x, y) end
local function _ui_color(r, g, b, a)
    local function linear(v)
        v = v / 255
        if v <= 0.04045 then return v / 12.92 end
        return ((v + 0.055) / 1.055) ^ 2.4
    end
    return _ui_colorClass(linear(r), linear(g), linear(b), a or 1)
end
local function _ui_visibility(w, v)
    local fn = _ui_member(w, "SetWidgetVisibility") or _ui_member(w, "SetVisibility")
    assert(type(fn) == "function", "UI_VISIBILITY_UNAVAILABLE")
    fn(w, v)
end
local function _ui_parent()
    local ok, t = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameUITools")
-- Ⓓⓤⓜⓟ Ⓢⓗⓐⓓⓞⓦ ⓉⒼ ⓈⒽⒹ_ⒸⒽ⓫
    if not ok or type(_ui_member(t, "GetMainControlBaseUI")) ~= "function" then return end
    local found, root = pcall(t.GetMainControlBaseUI)
    if not found or not _ui_valid(root) then return end
    local p = _ui_member(root, "CanvasPanel_0")
    if not _ui_valid(p) then p = _ui_member(root, "CanvasPanel_42") end
    if _ui_valid(p) then return p end
end
local function _ui_destroy(d)
    if not d then return end
    d.Visible = false
    if d.Event and d.Handle ~= nil then pcall(function() d.Event:Remove(d.Handle) end) end
    if d.GetKeyEvent and d.GetKeyHandle ~= nil then
        pcall(function() d.GetKeyEvent:Remove(d.GetKeyHandle) end)
    end
    if _ui_valid(d.Container) then pcall(function() d.Container:RemoveFromParent() end) end
    d.Submit = nil
    d.Event = nil
    d.Handle = nil
    d.Container = nil
    d.Parent = nil
    d.Input = nil
    d.Button = nil
    d.GetKeyButton = nil
    d.GetKeyEvent = nil
    d.GetKeyHandle = nil
    d.Status = nil
    d.Title = nil
    d.Detail = nil
    d.Hint = nil
    d.Design = nil
    d.Cache = nil
end

function UI.Build(kind, key, status, submit)
    local p = _ui_parent()
    if not p then return nil, "UI_NOT_READY" end
    local enums = UEnums.ESlateVisibility
    local passive = enums.SelfHitTestInvisible
    if enums.Visible == nil or passive == nil then return nil, "UI_ENUM_UNAVAILABLE" end
    local welcome = kind == "welcome"
    local W, H = welcome and 600 or 500, welcome and 276 or 248
    local scale = welcome and 0.8 or 1
    pcall(function()
        local v = p:GetCachedGeometry():GetLocalSize()
        if v.X > 24 and v.Y > 24 then scale = math.min(scale, (v.X - 24) / W, (v.Y - 24) / H) end
    end)
    local d = { Parent = p, Visible = false, Submit = submit, Scale = scale }
    local ok, buildError = pcall(function()
        local function make(class, outer)
            local w = CGame:NewObjectFromPath("/Script/UMG." .. class, outer)
            assert(_ui_valid(w), "UI_WIDGET_UNAVAILABLE")
            return w
        end
        d.Container = make("CanvasPanel", p)
        local design = make("CanvasPanel", d.Container)
        d.Design = design
-- Ｄｕｍｐ • ｂｙ • Ｓｈａｄｏｗ shadow_cheatss
        local artRoot = design
        local canCache, cache = pcall(make, "InvalidationBox", d.Container)
        if canCache and _ui_valid(cache) and type(_ui_member(cache, "SetCanCache")) == "function" then
            local attached = pcall(function()
                cache:AddChild(design)
                cache:SetCanCache(true)
                _ui_visibility(cache, passive)
            end)
            if attached then
                artRoot = cache
                d.Cache = cache
            end
        end
        local artSlot = d.Container:AddChildToCanvas(artRoot)
        artSlot:SetAutoSize(false)
        artSlot:SetPosition(_ui_vector(0, 0))
        artSlot:SetSize(_ui_vector(W, H))
        artSlot:SetZOrder(1)
        _ui_visibility(design, passive)
        local function add(w, x, y, ww, hh, z, dynamic)
            local slot = (dynamic and d.Container or design):AddChildToCanvas(w)
            slot:SetAutoSize(false)
            slot:SetPosition(_ui_vector(x, y))
            slot:SetSize(_ui_vector(ww, hh))
            slot:SetZOrder(z)
            return slot
        end
        local artwork = {}
        local function drawRect(x, y, ww, hh, c, z, opacity)
            local w = make("Border", d.Container)
            w:SetBrushColor(_ui_colorClass(c.R, c.G, c.B, opacity or 0.5))
            _ui_visibility(w, passive)
            add(w, x, y, ww, hh, z)
            return w
        end
        local function rect(x, y, ww, hh, c, z, opacity) artwork[#artwork + 1] = { X = x, Y = y, W = ww, H = hh, C = c, Z = z, A = opacity or 0.5, Order = #artwork + 1 } end
        local function renderArt()
            table.sort(artwork, function(a, b)
                if a.Z == b.Z then return a.Order > b.Order end
                return a.Z > b.Z
            end)
            local covered = {}
            local function put(out, x, y, w, h)
                if w > 0.00001 and h > 0.00001 then out[#out + 1] = { X = x, Y = y, W = w, H = h } end
            end
            for _, shape in ipairs(artwork) do
                local pieces = { { X = shape.X, Y = shape.Y, W = shape.W, H = shape.H } }
                for _, cover in ipairs(covered) do
                    local nextPieces = {}
                    for _, piece in ipairs(pieces) do
-- 𝕯𝖚𝖒𝖕 𝖇𝖞 𝕾𝖍𝖆𝖉𝖔w SHD_CHT
                        local x1 = math.max(piece.X, cover.X)
                        local y1 = math.max(piece.Y, cover.Y)
                        local x2 = math.min(piece.X + piece.W, cover.X + cover.W)
                        local y2 = math.min(piece.Y + piece.H, cover.Y + cover.H)
                        if x2 <= x1 or y2 <= y1 then
                            nextPieces[#nextPieces + 1] = piece
                        else
                            put(nextPieces, piece.X, piece.Y, piece.W, y1 - piece.Y)
                            put(nextPieces, piece.X, y2, piece.W, piece.Y + piece.H - y2)
                            put(nextPieces, piece.X, y1, x1 - piece.X, y2 - y1)
                            put(nextPieces, x2, y1, piece.X + piece.W - x2, y2 - y1)
                        end
                    end
                    pieces = nextPieces
                    if #pieces == 0 then break end
                end
                local changed = true
                while changed do
                    changed = false
                    for i = 1, #pieces do
                        local a = pieces[i]
                        for j = i + 1, #pieces do
                            local b = pieces[j]
                            local vertical = math.abs(a.X - b.X) < 0.00001 and math.abs(a.W - b.W) < 0.00001 and (math.abs(a.Y + a.H - b.Y) < 0.00001 or math.abs(b.Y + b.H - a.Y) < 0.00001)
                            local horizontal = math.abs(a.Y - b.Y) < 0.00001 and math.abs(a.H - b.H) < 0.00001 and (math.abs(a.X + a.W - b.X) < 0.00001 or math.abs(b.X + b.W - a.X) < 0.00001)
                            if vertical or horizontal then
                                local x, y = math.min(a.X, b.X), math.min(a.Y, b.Y)
                                a.W = math.max(a.X + a.W, b.X + b.W) - x
                                a.H = math.max(a.Y + a.H, b.Y + b.H) - y
                                a.X = x
                                a.Y = y
                                table.remove(pieces, j)
                                changed = true
                                break
                            end
                        end
                        if changed then break end
                    end
                end
                for _, piece in ipairs(pieces) do
                    drawRect(piece.X, piece.Y, piece.W, piece.H, shape.C, shape.Z, shape.A)
                end
                covered[#covered + 1] = shape
            end
            artwork = nil
        end
        local function sample(stops, t, opacity)
            t = math.max(0, math.min(1, t))
            local a, b, u
            if t <= 0.5 then
-- ᴅᴜᴍᴘ ʙʏ ꜱʜᴀᴅᴏᴡ ᴛɢ ꜱʜᴅ_ᴄʜᴛ
                a, b, u = stops[1], stops[2], t * 2
            else
                a, b, u = stops[2], stops[3], (t - 0.5) * 2
            end
            return _ui_color(a[1] + (b[1] - a[1]) * u, a[2] + (b[2] - a[2]) * u, a[3] + (b[3] - a[3]) * u, opacity)
        end
        local function panel(x, y, ww, hh, cut, stops, z, columns, opacity)
            columns = math.min(columns, 12)
            for i = 0, columns - 1 do
                local a = ww * i / columns
                local b = ww * (i + 1) / columns
                local inset = math.max(0, cut - math.min(a, ww - b))
                rect(x + a, y + inset, b - a, hh - inset * 2, sample(stops, (i + 0.5) / columns, opacity), z, opacity)
            end
        end
        local function rail(x, y, ww, hh, stops, z, columns)
            columns = math.min(columns, 12)
            for i = 0, columns - 1 do
                rect(x + ww * i / columns, y, ww / columns, hh, sample(stops, (i + 0.5) / columns), z)
            end
        end
        local function line(ax, ay, bx, by, th, c, z)
            local dx, dy = bx - ax, by - ay
            local len = math.sqrt(dx * dx + dy * dy)
            if len <= 0 then return end
            local angle
            if dx == 0 then
                angle = dy >= 0 and 90 or -90
            else
                angle = math.atan(dy / dx) * 180 / math.pi
                if dx < 0 then angle = angle + 180 end
            end
            local w = drawRect((ax + bx - len) / 2, (ay + by - th) / 2, len, th, c, z, z >= 7 and 1 or 0.5)
            w:SetRenderTransformPivot(_ui_vector(0.5, 0.5))
            w:SetRenderAngle(angle)
        end
        local slate = import("SlateColor")
