-- HỆ THỐNG MENU VIP NATIVE (CHẠY TRỰC TIẾP TỪ SETTING GAME)
-- ========================================== 

-- ==========================================
-- 🚀 SPEED BOOST LOGIC (100% WORKING)
-- ==========================================
_G.MemoryConfig = _G.MemoryConfig or {
    SpeedHack = false,
    SpeedPercent = 150,
    ServerSync = true,
    SyncInterval = 0.25,
    SyncMethod = "Attribute",
    Randomize = true,
    RandomRange = 0.15,
}

_G.SpeedHackState = _G.SpeedHackState or {
    active = false,
    timer = nil,
    modifyId = nil,
    currentChar = nil,
    syncTimer = 0,
    lastPos = nil,
    lastVel = nil,
    currentSpeed = 150,
}

local function RemoveSpeedModify(char)
-- 𝕯𝖚𝖒𝖕_𝖇𝖞_𝕾𝖍𝖆𝖉𝖔𝖜_𝕾𝕳𝕯 SHD_CHT
    if not slua.isValid(char) or not char.AttrModifyComp then return end
    if _G.SpeedHackState.modifyId then
        pcall(function() char.AttrModifyComp:RemoveModifyItemFromCache(_G.SpeedHackState.modifyId) end)
        _G.SpeedHackState.modifyId = nil
    end
end

local function ApplySpeedModify(char)
    if not slua.isValid(char) or not char.AttrModifyComp then return end
    RemoveSpeedModify(char)
    
    local base = _G.MemoryConfig.SpeedPercent or 150
    local finalSpeed = base
    if _G.MemoryConfig.Randomize then
        local variation = 1.0 + (math.random() * 2 * _G.MemoryConfig.RandomRange) - _G.MemoryConfig.RandomRange
        finalSpeed = base * variation
        if finalSpeed < 100 then finalSpeed = 100 end
        if finalSpeed > 500 then finalSpeed = 500 end
    end
    _G.SpeedHackState.currentSpeed = finalSpeed
    
    local rate = (finalSpeed / 100.0) - 1.0
    pcall(function()
        _G.SpeedHackState.modifyId = char.AttrModifyComp:AddModifyItemAndCache("SpeedRate", 0, rate, true, char, false)
    end)
end

local function DoServerSync(char)
    if not _G.MemoryConfig.ServerSync then return end
    if not char or not slua.isValid(char) then return end
    
    pcall(function()
        local cm = char.CharacterMovement or char.STCharacterMovement
        if not slua.isValid(cm) then return end
        
        local pos = char:K2_GetActorLocation()
        if not pos then return end
        
        local pc = char:GetPlayerControllerSafety()
        if not slua.isValid(pc) then return end
        
        if _G.MemoryConfig.SyncMethod == "ServerMove" then
            local vel = cm.Velocity or char:GetVelocity()
            if vel then
                local timestamp = os.clock()
                local accel = FVector(0, 0, 0)
                local offsetX = math.random(-3, 3)
                local offsetY = math.random(-3, 3)
                local spoofedPos = FVector(pos.X + offsetX, pos.Y + offsetY, pos.Z - 20 + math.random(-5, 5))
                if cm.ServerMove then
-- 𝖣𝗎𝗆𝗉 𝖻𝗒 𝲲𝗁𝖺𝖽𝗈𝗐 𝓣𝓖 shadow_cheatss
                    cm:ServerMove(timestamp, accel, spoofedPos, vel)
                end
            end
        end
        
        if _G.MemoryConfig.SyncMethod == "Teleport" then
            if _G.CustomFeatures and _G.CustomFeatures.FlyMode and _G.CustomFeatures.FlyMode.ENABLED then
                local groundZ = pos.Z - 250 + math.random(-20, 20)
                local spoofedPos = FVector(pos.X + math.random(-5, 5), pos.Y + math.random(-5, 5), groundZ)
                if char.ServerTeleport then
                    char:ServerTeleport(spoofedPos, char:K2_GetActorRotation())
                end
            end
        end
        
        if _G.MemoryConfig.SyncMethod == "Attribute" then
            if char.ForceNetUpdate then char:ForceNetUpdate() end
        end
    end)
end

local function UpdateSpeedHack()
    if not _G.MemoryConfig.SpeedHack then return end
    
    local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
    if not slua.isValid(pc) then return end
    local char = pc:GetPlayerCharacterSafety()
    if not slua.isValid(char) then return end
    
    if _G.SpeedHackState.currentChar ~= char then
        if _G.SpeedHackState.currentChar then RemoveSpeedModify(_G.SpeedHackState.currentChar) end
        _G.SpeedHackState.currentChar = char
    end
    ApplySpeedModify(char)
    
    if _G.MemoryConfig.ServerSync then
        local dt = 0.033
        _G.SpeedHackState.syncTimer = (_G.SpeedHackState.syncTimer or 0) + dt
        if _G.SpeedHackState.syncTimer >= _G.MemoryConfig.SyncInterval then
            _G.SpeedHackState.syncTimer = 0
            DoServerSync(char)
        end
    end
end

function SetMemorySpeedHack(enabled)
    _G.MemoryConfig.SpeedHack = enabled
    if enabled then
        if _G.SpeedHackState.timer then return end
        _G.SpeedHackState.active = true
-- Dump by Shadow TG SHD_CHT
        _G.SpeedHackState.syncTimer = 0
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if slua.isValid(pc) and pc.AddGameTimer then
            _G.SpeedHackState.timer = pc:AddGameTimer(0.2, true, UpdateSpeedHack)
        end
    else
        _G.SpeedHackState.active = false
        if _G.SpeedHackState.timer then
            local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
            if slua.isValid(pc) and pc.RemoveGameTimer then
                pc:RemoveGameTimer(_G.SpeedHackState.timer)
            end
            _G.SpeedHackState.timer = nil
        end
        if _G.SpeedHackState.currentChar then
            RemoveSpeedModify(_G.SpeedHackState.currentChar)
            _G.SpeedHackState.currentChar = nil
        end
    end
end

function SetMemorySpeedPercent(val)
    _G.MemoryConfig.SpeedPercent = val
    if _G.MemoryConfig.SpeedHack and _G.SpeedHackState.currentChar then
        ApplySpeedModify(_G.SpeedHackState.currentChar)
    end
end

function _G.InitModMenuTab()
    if _G.ModMenuInitialized then return end
    -- Do not mark initialized until the required native settings UI hooks exist.
    -- This permits a safe retry if game modules load late.

    -- This script's custom menu is English-only (no language-selection dialog).
    _G.LexusLang = "EN"
    local function T(_, enText)
        return enText or _
    end

    _G.LexusConfig = _G.LexusConfig or {}
    if _G.LexusConfig.FastCar == nil then _G.LexusConfig.FastCar = false end
    _G.LexusState.CustomTextData = _G.LexusState.CustomTextData or {
        OuterSpeed = 10, InnerSpeed = 10, OuterRecoil = 0, HRecoil = 0.3, VRecoil = 0.3, MagicHead = 1.0, MagicBody = 1.0, MagicLegs = 1.0, IpadViewFOV = 120, IpadViewVehicleFOV = 120,
        BugManRatio = 133,
        FastCarSpeed = 2000,
        WeaponGlowThickness = 3, WeaponGlowColor = 5,
        ColorV3Hidden = 1, ColorV3Visible = 2, ColorV3Thickness = 4, OutlineColor = 4
    }
    if _G.LexusState.CustomTextData.FastCarSpeed == nil then
        _G.LexusState.CustomTextData.FastCarSpeed = 2000
    end

    local LocUtil = _G.LocUtil
    if not LocUtil and package.loaded["client.common.LocUtil"] then
        LocUtil = require("client.common.LocUtil")
    end
    
-- 𝗗𝘂𝗺𝗽 𝗯𝘆 𝗦𝗵𝗮𝗱𝗼𝘄 𝗧𝗚 𝗦𝗛𝗗_𝗖𝗛𝗧
    -- 1. TẠO BẢNG ID ẢO VỚI TEXT MỚI (Hỗ trợ 2 ngôn ngữ)
    local FakeTextMap = {
        [999000] = "✦SHADOW MENU✦",
        [999001] = "ESP",
        [999002] = "ESP",
        [999003] = "IPAD VIEW",
        [999009] = "FASTEST SPEED",
        [999008] = "PREMIUM AIM",
        [999005] = "SKINS"
    }

    -- 2. HOOK TOÀN BỘ HÀM ĐỌC TEXT CỦA GAME (FIX LỖI TRỐNG THANH TAB)
    if LocUtil and not LocUtil._IsModMenuHooked_V2 then
        local hookFuncs = {"GetLocalizeResStr", "GetText", "GetTextByID", "GetLocalText", "GetLocalizeStr"}
        for _, funcName in ipairs(hookFuncs) do
            if LocUtil[funcName] then
                local old_func = LocUtil[funcName]
                LocUtil[funcName] = function(id)
                    if FakeTextMap[id] then
                        return FakeTextMap[id]
                    end
                    if type(id) == "string" and not tonumber(id) then
                        return id
                    end
                    if old_func then
                        return old_func(id)
                    end
                    return ""
                end
            end
        end
        LocUtil._IsModMenuHooked_V2 = true
    end

    local SettingPageDefine = require("client.logic.NewSetting.SettingPageDefine")
    local SettingCatalog = require("client.logic.NewSetting.SettingCatalog")
    
    if not SettingPageDefine.ModMenu then
        local AliasMap = require("client.slua.umg.NewSetting.Item.AliasMap")
        
        -- Kept features: ESP (former ESP2), iPad View, Fast Speed, Premium Aim, Skins.
        -- Former ESP2 is the sole main ESP category (all existing controls).
        -- Try refreshing the currently visible settings controller immediately
        -- after a group toggle. No extra timer, popup, or menu navigation needed.
        local function RefreshESPMenuUI(control)
            local methods = {"RefreshItem", "RefreshData", "RefreshView", "RefreshUI", "UpdateUI", "UpdateView", "OnRefresh"}
            local visited = {}
            local function tryObject(obj)
                if not obj or visited[obj] then return end
                visited[obj] = true
                for _, name in ipairs(methods) do
                    pcall(function()
                        local fn = obj[name]
                        if type(fn) == "function" then fn(obj) end
                    end)
                end
            end
            tryObject(control)
            local parents = {"Parent", "parent", "Owner", "owner", "ParentPanel", "parentPanel", "View", "view", "ItemList", "itemList", "Widget", "widget"}
            local current = control
            for _ = 1, 3 do
                if not current then break end
                local nextObject
                for _, field in ipairs(parents) do
                    local ok, candidate = pcall(function() return current[field] end)
                    if ok and candidate and candidate ~= current then
                        tryObject(candidate)
                        if not nextObject then nextObject = candidate end
                    end
                end
                local ok, candidate = pcall(function()
                    if type(current.GetParent) == "function" then return current:GetParent() end
                end)
                if ok and candidate and candidate ~= current then
                    tryObject(candidate)
                    nextObject = candidate
                end
                current = nextObject
            end
        end

        -- Match the donor 3.lua's native settings event refresh contract.
        -- A bulk change therefore updates all currently displayed rows live.
        local ESPSettingsEventType, ESPSettingsEventID = -14050701, 2
        local function ESPSelectedValue(c,v) if v==nil then return c end return v end
        local StackESP = {
            {Key="VIPServerESP_All",UI=AliasMap.Switcher,Text="ALL ESP (ON / OFF)",SwitcherText={"All On","All Off"},
                LunarBulk=true,EventType=ESPSettingsEventType,EventID=ESPSettingsEventID,
                GetFunc=function() return _G.LunarFeatures and _G.LunarFeatures.GetESPAll(2) or false end,
                SetFunc=function(c,v)
                    local ok = _G.LunarFeatures and _G.LunarFeatures.SetESPAll(2,ESPSelectedValue(c,v))
                    if ok then RefreshESPMenuUI(c) end
                    return ok == true
                end},
            {Key="VIPServerESP_Name",UI=AliasMap.Switcher,Text="ESP NAME",EventType=ESPSettingsEventType,EventID=ESPSettingsEventID,
                GetFunc=function() return _G.g_vipserver_ESPOptions and _G.g_vipserver_ESPOptions.Name end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetESP(2,"Name",ESPSelectedValue(c,v)) end},
            {Key="VIPServerESP_Line",UI=AliasMap.Switcher,Text="ESP LINE",EventType=ESPSettingsEventType,EventID=ESPSettingsEventID,
                GetFunc=function() return _G.g_vipserver_ESPOptions and _G.g_vipserver_ESPOptions.Line end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetESP(2,"Line",ESPSelectedValue(c,v)) end},
            {Key="VIPServerESP_Box",UI=AliasMap.Switcher,Text="ESP BOX",EventType=ESPSettingsEventType,EventID=ESPSettingsEventID,
                GetFunc=function() return _G.g_vipserver_ESPOptions and _G.g_vipserver_ESPOptions.Box end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetESP(2,"Box",ESPSelectedValue(c,v)) end},
            {Key="VIPServerESP_Health",UI=AliasMap.Switcher,Text="ESP HEALTH",EventType=ESPSettingsEventType,EventID=ESPSettingsEventID,
                GetFunc=function() return _G.g_vipserver_ESPOptions and _G.g_vipserver_ESPOptions.Health end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetESP(2,"Health",ESPSelectedValue(c,v)) end},
            {Key="VIPServerESP_Distance",UI=AliasMap.Switcher,Text="ESP DISTANCE",EventType=ESPSettingsEventType,EventID=ESPSettingsEventID,
                GetFunc=function() return _G.g_vipserver_ESPOptions and _G.g_vipserver_ESPOptions.Distance end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetESP(2,"Distance",ESPSelectedValue(c,v)) end},
            {Key="VIPServerESP_Skeleton",UI=AliasMap.Switcher,Text="ESP SKELETON",EventType=ESPSettingsEventType,EventID=ESPSettingsEventID,
                GetFunc=function() return _G.g_vipserver_ESPOptions and _G.g_vipserver_ESPOptions.Skeleton end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetESP(2,"Skeleton",ESPSelectedValue(c,v)) end},
            {Key="VIPServerESP_Counter",UI=AliasMap.Switcher,Text="ESP COUNTER",EventType=ESPSettingsEventType,EventID=ESPSettingsEventID,
                GetFunc=function() return _G.g_vipserver_ESPOptions and _G.g_vipserver_ESPOptions.Counter end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetESP(2,"Counter",ESPSelectedValue(c,v)) end},
        }

        -- In the native selector, selecting the already-selected "All On" option
        -- can skip SetFunc even when an individual option was subsequently turned off.
        -- Apply the donor 3.lua's bulk-only repeat-selection behavior safely.
        pcall(function()
            local cls=require("client.slua.umg.NewSetting.Item.Setting_Option_Switcher")
            local features=_G.LunarFeatures
            if features and type(features.InstallNativeBulkSwitch)=="function" then
                features.InstallNativeBulkSwitch(cls)
            end
        end)

        local StackIpad = {
            { Key = "ModMenu_Ipad_Ex", UI = AliasMap.TitleSwitcher, Text = T("▶ Ipad View", "▶ Ipad View"), ExpandIndex = 0, GetFunc = function() return _G.LexusConfig.IpadView end, SetFunc = function(c,v) _G.LexusConfig.IpadView = v return true end },
            { Key = "ModMenu_Ipad_FOV", UI = AliasMap.Slider, Text = T("  FOV Value", "  FOV Value"), ExpandHandle = "ModMenu_Ipad_Ex", MinValue = 1, MaxValue = 100, min = 1, max = 100, GetFunc = function() return (_G.LexusState.CustomTextData.IpadViewFOV or 120) - 90 end, SetFunc = function(c,v) _G.LexusState.CustomTextData.IpadViewFOV = 90 + v return true end },
            { Key = "ModMenu_IpadVeh_Ex", UI = AliasMap.TitleSwitcher, Text = T("▶ Ipad View Vehicle"), ExpandIndex = 0, GetFunc = function() return _G.LexusConfig.IpadViewVehicle end, SetFunc = function(c,v) _G.LexusConfig.IpadViewVehicle = v return true end },
            { Key = "ModMenu_IpadVeh_FOV", UI = AliasMap.Slider, Text = T("  Vehicle FOV Value"), ExpandHandle = "ModMenu_IpadVeh_Ex", MinValue = 1, MaxValue = 100, min = 1, max = 100, GetFunc = function() return (_G.LexusState.CustomTextData.IpadViewVehicleFOV or 120) - 90 end, SetFunc = function(c,v) _G.LexusState.CustomTextData.IpadViewVehicleFOV = 90 + v return true end },
        }

        local StackSpeed = {
{ Key = "ModMenu_SpeedHack_Ex", UI = AliasMap.TitleSwitcher, Text = T("🚀 Speed Boost", "🚀 Speed Boost"), ExpandIndex = 0, GetFunc = function() return _G.MemoryConfig.SpeedHack end, SetFunc = function(c,v) SetMemorySpeedHack(v) return true end },
{ Key = "ModMenu_SpeedPercent", UI = AliasMap.Slider, Text = "Speed % (100-500)", ExpandHandle = "ModMenu_SpeedHack_Ex", MinValue = 0, MaxValue = 100, GetFunc = function() return ((_G.MemoryConfig.SpeedPercent or 150) - 100) / 4 end, SetFunc = function(c,v) SetMemorySpeedPercent(100 + (v * 4)) return true end },
            { Key = "ModMenu_FastCar_Ex", UI = AliasMap.TitleSwitcher, Text = "FLYING CAR / FAST CAR", ExpandIndex = 0,
                GetFunc = function() return _G.LexusConfig.FastCar == true end,
                SetFunc = function(c,v) _G.LexusConfig.FastCar = (v == true or v == 1) return true end },
            { Key = "ModMenu_FastCar_Speed", UI = AliasMap.Slider, Text = "Vehicle Speed Level (1-100) • Banrix. So please play safe",
                ExpandHandle = "ModMenu_FastCar_Ex", MinValue = 1, MaxValue = 100, min = 1, max = 100,
                GetFunc = function() return math.floor((_G.LexusState.CustomTextData.FastCarSpeed or 3000) / 60) end,
                SetFunc = function(c,v) _G.LexusState.CustomTextData.FastCarSpeed = v * 60 return true end },
        }

        -- Donor 2.lua: THIRD tab, Premium Aim (with native settings controls).
        local StackPremiumAim = {
            {Key="LunarAim",UI=AliasMap.TitleSwitcher,Text="PREMIUM AIMBOT",ExpandIndex=0,
                GetFunc=function() return _G.LunarFeatures and _G.LunarFeatures.Settings.AimEnabled end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetAim(v) end},
            {Key="LunarAimSpeed",UI=AliasMap.Slider,Text="Aim speed (100-120)",ExpandHandle="LunarAim",
                MinValue=100,MaxValue=120,Min=100,Max=120,min=100,max=120,
                GetFunc=function() return _G.LunarFeatures and _G.LunarFeatures.Settings.AimSpeed or 100 end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetAimSpeed(v) end},
            {Key="LunarAimTarget",UI=AliasMap.Switcher,Text="Aim target",ExpandHandle="LunarAim",
