                GetFunc=function() return _G.LunarFeatures and _G.LunarFeatures.Settings.AimTarget or 1 end,
                SetFunc=function(c,v) return _G.LunarFeatures and _G.LunarFeatures.SetAimTarget(v) end},
        }

        -- Main speed tab: Premium Aim -> Speed Boost -> Flying Car.
        -- Only reorder existing menu items; their callbacks stay exactly the same.
