        StackSpeed={}
        for _,item in ipairs(StackPremiumAim) do StackSpeed[#StackSpeed+1]=item end
        for _,item in ipairs(priorSpeed) do StackSpeed[#StackSpeed+1]=item end
        -- The existing seven-color Wall controls follow the iPad View options.
