                SwitcherText=wallColorNames,SwitcherValue={1,2,3,4,5,6,7},
                GetFunc=function() return _G.LunarFeatures and _G.LunarFeatures.Settings[field] or 1 end,
                SetFunc=function(c,v)
                    local selected=v
                    if selected==nil then selected=c end
                    return _G.LunarFeatures and _G.LunarFeatures.SetWallColor(field,selected)
                end,
            }
        end

        -- Optional Egg ESP below the existing iPad/Wall controls.
        -- Activation is demand-driven: no scan or timer while disabled.
        StackIpad[#StackIpad+1] = {
            Key="ModMenu_LuckyEggESP", UI=AliasMap.Switcher, Text="EGG ESP",
            GetFunc=function() return _G.LUCKY_EGG_ESP_ON == true end,
            SetFunc=function(c,v)
                local enabled = v
                if enabled == nil and type(c) == "boolean" then enabled = c end
                _G.LUCKY_EGG_ESP_ON = (enabled == true or enabled == 1)
                if _G.LUCKY_EGG_ESP_ON then
                    if type(_G.StartLuckyEgg)=="function" then pcall(_G.StartLuckyEgg) end
                else
                    if type(_G.StopLuckyEgg)=="function" then pcall(_G.StopLuckyEgg) end
                end
                return true
            end
        }

        local StackSkin = {
            { Key = "ModMenu_ModSkin", UI = AliasMap.Switcher, Text = T("Hệ Thống Mod Skin VIP (Mở túi đồ chọn)", "VIP Mod Skin System (Open inventory)"), GetFunc = function() return _G.LexusConfig.ModSkin end, SetFunc = function(c,v)
                _G.LexusConfig.ModSkin = v
                if v == true then
                    pcall(function() if _G.AddOutfit and _G.AddOutfit.start then _G.AddOutfit.start() end end)
                end
                return true
            end },
            { Key = "ModMenu_SkinDeadBox", UI = AliasMap.Switcher, Text = T("Skin Hòm Xác (Ăn theo skin Súng/Xe)", "Deadbox Skin (Sync with Weapon)"), GetFunc = function() return _G.LexusConfig.SkinDeadBox end, SetFunc = function(c,v) _G.LexusConfig.SkinDeadBox = v return true end },
            { Key = "ModMenu_SkinAttachment", UI = AliasMap.Switcher, Text = T("Skin Phụ Kiện Súng (Nòng, Tay cầm...)", "Weapon Attachment Skin"), GetFunc = function() return _G.LexusConfig.SkinAttachment end, SetFunc = function(c,v) _G.LexusConfig.SkinAttachment = v return true end },
-- 𝓓𝓾𝓶𝓹 𝓫𝔂 𝓢𝓱𝓪𝓭𝓸𝔀 𝓣𝓖 𝓢𝓗𝓓_𝓒𝓗𝓣
            { Key = "ModMenu_KillMessage", UI = AliasMap.Switcher, Text = T("Kill Messenger VIP", "VIP Kill Messenger"), GetFunc = function() return _G.LexusConfig.KillMessage end, SetFunc = function(c,v) _G.LexusConfig.KillMessage = v return true end },
            { Key = "ModMenu_KillCountUI", UI = AliasMap.Switcher, Text = T("Bộ Đếm Kill (Hiển thị số Kill vũ khí)", "Kill Counter UI"), GetFunc = function() return _G.LexusConfig.KillCountUI end, SetFunc = function(c,v) _G.LexusConfig.KillCountUI = v return true end },
            { Key = "ModMenu_SkinOpenLink", UI = AliasMap.Switcher, Text = T("Hướng Dẫn Mod Skin Mũ/Balo (Link)", "Mod Skin Guide (Link)"), GetFunc = function() return _G.LexusConfig.SkinOpenLink end, SetFunc = function(c,v) _G.LexusConfig.SkinOpenLink = v; if v == true then pcall(function() local Web = require("client.slua.logic.url.logic_webview_sdk"); if Web and Web.OpenURL then Web:OpenURL("https://chat.whatsapp.com/IIpN5GcBv2w6GhG5Z8vCBX") end end) end return true end },
        }

        SettingPageDefine.ModMenu = {
            Key = "ModMenu",
            Text = 999000, 
            UIKey = "Setting_Page_Privacy", 
            Category = {
                { Key = "Cat_ESP", Text = 999001, Stack = StackESP },
                { Key = "Cat_IPad", Text = 999003, Stack = StackIpad },
                { Key = "Cat_Speed", Text = 999009, Stack = StackSpeed },
                { Key = "Cat_Skin", Text = 999005, Stack = StackSkin }
            }
        }
        
        table.insert(SettingCatalog, SettingPageDefine.ModMenu)
    end

    local UIManager = _G.UIManager
    if UIManager and not UIManager._IsModMenuHooked then
        local old_ShowUI = UIManager.ShowUI
        UIManager.ShowUI = function(config, ...)
            local args = {...}
            local n = select('#', ...) 
            
            if config and config.keyName then
                local lowerKeyName = string.lower(config.keyName)
                if string.find(lowerKeyName, "setting_main") and not string.find(lowerKeyName, "custom") then
                    local catalog = args[1]
                    if type(catalog) == "table" and catalog[1] and type(catalog[1]) == "table" and catalog[1].Key then
                        local count = 0
                        for _, page in ipairs(catalog) do
                            if type(page) == "table" and page.Key == "ModMenu" then
                                count = count + 1
                            end
                        end
                        -- Stable on fresh loads and when the game reuses an old catalog.
                        if count ~= 1 or catalog[#catalog] ~= SettingPageDefine.ModMenu then
                            for i = #catalog, 1, -1 do
                                if type(catalog[i]) == "table" and catalog[i].Key == "ModMenu" then
                                    table.remove(catalog, i)
                                end
                            end
                            catalog[#catalog + 1] = SettingPageDefine.ModMenu
                        end
                    end
                end
            end
            local table_unpack = table.unpack or unpack
            return old_ShowUI(config, table_unpack(args, 1, n))
        end
-- 𝙳𝚞𝚖𝚙 𝚋𝚢 𝚂𝚑𝚊𝚍𝚘𝘸 𝚃𝙶 𝚂𝙷𝙳_𝙲𝙷𝚃
        UIManager._IsModMenuHooked = true
    end
    _G.ModMenuInitialized = UIManager ~= nil and UIManager._IsModMenuHooked == true
end

local function ShowLexusVIPMenu()
    local licenseRuntime=masterESPLicenseInstance
    if not licenseRuntime or not licenseRuntime:isActive() then return end
    if not licenseRuntime.welcomeShownThisSession then return end
    local welcome=licenseRuntime.welcome
    if welcome and welcome._data and welcome._data.Visible then return end
    if _G.LexusMenuAlreadyShown then return end
    if _G.LexusState.MenuStep ~= 0 then return end

    _G.LexusLang = "EN"
    pcall(function()
        local Msg = require("client.slua.logic.common.logic_common_msg_box")
        if not Msg or not Msg.Show then return end

        local function Step_ScamAlert()
            Msg.Show(1, "SCAM ALERT", "Join my Telegram to avoid scammers owner SHADOW",
                function()
                    local Web = require("client.slua.logic.url.logic_webview_sdk")
                    if Web and Web.OpenURL then
                        Web:OpenURL("https://chat.whatsapp.com/IIpN5GcBv2w6GhG5Z8vCBX")
                    end
                end,
                function() end, "JOIN", "CLOSE")
            _G.LexusState.MenuStep = 99
            _G.LexusMenuAlreadyShown = true
        end

        local function Step_Welcome()
            Msg.Show(1, "+ +92 [ 03153875433 ]",
                "Hi, SHADOW here The premium is now inside Game Settings!\nIMPORTANT: Enable fewer features to avoid lag. Play safe!",
                function()
                    _G.InitModMenuTab()
                    Notify("VIP MOD MENU ADDED!\nOpen Settings (Gear icon) -> VIP MOD MENU to toggle features.")
                    Step_ScamAlert()
                end,
                function() end, "OPEN GAME MENU", "CLOSE")
        end

        _G.LexusState.MenuStep = 1
        Step_Welcome() -- English by default: no language-selection popup.
    end)
end

