-- Original 1.lua bottom-left red PREMIUM CHEATS HUD label.
local DungCuOverlay = { Widget = nil, Slot = nil }

local function CleanUpPermanentDungCu()
    if DungCuOverlay.Widget and slua.isValid(DungCuOverlay.Widget) then
        pcall(function() DungCuOverlay.Widget:RemoveFromParent() end)
        pcall(function() DungCuOverlay.Widget:ConditionalBeginDestroy() end)
    end
    DungCuOverlay.Widget = nil
    DungCuOverlay.Slot = nil
end

local DungCuLastPositionTime = -1000
local DungCuLastParent = nil
local function EnsurePermanentDungCu()
    if _G.PlayerMapMarker and not _G.DungCu_Protected_V2 then
        local old_IsOurESPWidget = _G.PlayerMapMarker.IsOurESPWidget
        _G.PlayerMapMarker.IsOurESPWidget = function(w)
            if DungCuOverlay.Widget and w == DungCuOverlay.Widget then return false end
            if _G.FovCircleOverlay and _G.FovCircleOverlay.Container and w == _G.FovCircleOverlay.Container then return false end
            if old_IsOurESPWidget then return old_IsOurESPWidget(w) end
            return false
        end
        _G.DungCu_Protected_V2 = true
    end

    if DungCuOverlay.Widget and slua.isValid(DungCuOverlay.Widget) then
        local now = os.clock()
        if now - DungCuLastPositionTime < 0.5 and now >= DungCuLastPositionTime then return end
        DungCuLastPositionTime = now
        pcall(function() DungCuOverlay.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
        pcall(function()
            if DungCuOverlay.Slot then
                local ui_util = require("client.common.ui_util")
                local vp = ui_util and ui_util.GetViewportSize()
                if vp then
                    local FVector2D = import("Vector2D") or _G.FVector2D

                    local targetX = 120.0
                    local targetY = vp.Y - 60.0

                    local parentCanvas = DungCuOverlay.Widget:GetParent()
                    if slua.isValid(parentCanvas) then
-- Ｄｕｍｐ ｂｙ Ｓｈａｄｏｗ ＴＧ ＳＨＤ_ＣＨＴ
                        local cg = parentCanvas:GetCachedGeometry()
                        local SBL = import("SlateBlueprintLibrary") or import("/Script/UMG.SlateBlueprintLibrary")
                        if cg and SBL and SBL.AbsoluteToLocal then
                            local centerPt = SBL.AbsoluteToLocal(cg, FVector2D(targetX, targetY))
                            if centerPt then
                                targetX = centerPt.X
                                targetY = centerPt.Y
                            end
                        end
                    end
                    DungCuOverlay.Slot:SetPosition(FVector2D(targetX, targetY))
                end
            end
        end)
        return
    end

    local ParentCanvas = nil
    pcall(function()
        local InGameUITools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        local MainControlBaseUI = InGameUITools and InGameUITools.GetMainControlBaseUI()
        if MainControlBaseUI and slua.isValid(MainControlBaseUI) then
            ParentCanvas = MainControlBaseUI.CanvasPanel_0
            if not slua.isValid(ParentCanvas) then ParentCanvas = MainControlBaseUI.CanvasPanel_42 end
        end
    end)

    if not ParentCanvas or not slua.isValid(ParentCanvas) then return end

    local txtTitle = nil
    pcall(function() txtTitle = CGame:NewObjectFromPath("/Script/UMG.TextBlock", ParentCanvas) end)
    if txtTitle and slua.isValid(txtTitle) then
        pcall(function()
            txtTitle:SetText("TG: @SHADOW_CHEATSS")
            local FLinearColor = import("LinearColor") or _G.FLinearColor
            local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
            local redLinear = FLinearColor and FLinearColor(1.0, 0.0, 0.0, 1.0) or { R = 255, G = 0, B = 0, A = 255 }
            if FSlateColor then
                txtTitle:SetColorAndOpacity(FSlateColor(redLinear))
            else
                txtTitle:SetColorAndOpacity(redLinear)
            end

            if txtTitle.Font then
                local font = txtTitle.Font
                font.Size = 12
                txtTitle.Font = font
            end

            local FVector2D = import("Vector2D") or _G.FVector2D
            txtTitle:SetRenderScale(FVector2D(1.0, 1.0))
            txtTitle:SetRenderTransformPivot(FVector2D(0.5, 0.5))
            txtTitle:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
        end)

        local txtSlot = ParentCanvas:AddChildToCanvas(txtTitle)
        if txtSlot then
            pcall(function()
                txtSlot:SetAutoSize(true)
                local FVector2D = import("Vector2D") or _G.FVector2D

                txtSlot:SetAlignment(FVector2D(0.0, 1.0))
                txtSlot:SetZOrder(9999)
            end)
            DungCuOverlay.Slot = txtSlot
        end
        DungCuOverlay.Widget = txtTitle
    end
end

-- ========================================================================
-- LUCKY EGG ESP (item IDs 2230001..2230004)
-- Isolated overlay module: never changes existing ESP, Skins or license logic.
-- Deliberately no polling on startup: activated only by the EGG ESP switch.
-- ========================================================================
local LUCKY_EGG_IDS = {
    [2230001] = {name="Lv.1 Lucky Egg", color={R=150,G=255,B=150,A=255}},
    [2230002] = {name="Lv.2 Lucky Egg", color={R=100,G=200,B=255,A=255}},
    [2230003] = {name="Lv.3 Lucky Egg", color={R=200,G=150,B=255,A=255}},
    [2230004] = {name="Lv.4 Lucky Egg", color={R=255,G=215,B=50,A=255}},
}
_G.LUCKY_EGG_ESP_ON = _G.LUCKY_EGG_ESP_ON == true
_G.LUCKY_EGG_COUNT = _G.LUCKY_EGG_COUNT or {total=0, picked=0}
local eggTimerOwner = nil
local eggScanWorld = nil
local eggActorsCache = {}
local eggLastScan = -1e12
local eggClasses = nil
local eggClassRetryAt = -1e12
local eggNextStartAttempt = 0

-- Preserve the supplied pickup path only when an existing external
-- LUCKY_EGG_PICKUP setting explicitly enables it; EGG ESP alone is visual.
local function LuckyEggPickupOn()
    if type(_G.AK_GetVal) ~= "function" then return false end
    local ok,value=pcall(_G.AK_GetVal,"LUCKY_EGG_PICKUP")
    return ok and (value == true or value == 1)
end

local function GetPickupItemID(pickup)
    if not (slua and slua.isValid and slua.isValid(pickup)) then return nil end
    local id
    pcall(function() id=pickup.ItemID end)
    if not id then pcall(function() id=pickup.ItemId end) end
    if not id then pcall(function() id=pickup:GetItemID() end) end
    if not id then pcall(function() id=pickup.PickupItemID end) end
    if not id then pcall(function() id=pickup:GetPickupItemID() end) end
    if not id then pcall(function()
        local data=pickup.PickUpData
        if data then id=data.ItemID or data.ItemId end
    end) end
    return tonumber(id)
end

local function CollectLuckyEggActors(world, now)
    local result, seen = {}, {}
    if not world then return result end
    local GS
    pcall(function() GS=import("GameplayStatics") end)
    if not (GS and GS.GetAllActorsOfClass) then return result end

    -- Resolve compatible classes once rather than import every class every tick.
    -- Retry infrequently if the game has not loaded these classes yet.
    if not eggClasses or (#eggClasses==0 and now>=eggClassRetryAt) then
        eggClasses={}
        for _,name in ipairs({
            "PickUpWrapperActor", "PickupWrapperActor", "BP_PickUpWrapperActor_C",
            "PickUpWrapperActor_C", "PickupActor", "PickupBaseActor",
        }) do
            local ok, cls=pcall(import,name)
            if ok and cls then eggClasses[#eggClasses+1]=cls end
        end
        eggClassRetryAt=now+8.0
    end
    for _,cls in ipairs(eggClasses) do
        local actors={}
        local ok=pcall(function() GS.GetAllActorsOfClass(world,cls,actors) end)
        if ok and actors then
            -- Both Lua tables and UE TArray-style wrappers may be returned.
            local count=0
            pcall(function()
                count=type(actors.Num)=="function" and actors:Num() or #actors
            end)
            for i=1,math.min(count,3000) do
                local a
                pcall(function()
                    a=type(actors.Get)=="function" and actors:Get(i-1) or actors[i]
                end)
                if a and not seen[a] then
                    seen[a]=true
                    local id=GetPickupItemID(a)
                    if id and LUCKY_EGG_IDS[id] then
                        result[#result+1]={actor=a,id=id}
                    end
                end
            end
        end
    end
    return result
end

function _G.LuckyEggLoop()
    if _G._MOD_EXPIRED or _G.LicenseValid~=true then return end
    local espOn=_G.LUCKY_EGG_ESP_ON == true
    local pickOn=LuckyEggPickupOn()
    if not espOn and not pickOn then return end
    local player=GameplayData and GameplayData.GetPlayerCharacter()
    if not (slua and slua.isValid and slua.isValid(player)) then return end
    local pc=slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
    if not (pc and slua.isValid(pc)) then return end
    local hud
    pcall(function() hud=pc:GetHUD() end)
    if not (hud and slua.isValid(hud)) then return end
    local myPos
    pcall(function() myPos=player:K2_GetActorLocation() end)
    if not myPos then return end
    local now=os.clock()
    local world
    pcall(function() world=slua.getWorld() end)
    if not world then return end
    -- Heavy actor discovery runs at most once every three seconds, not every
    -- frame or every 0.5s as in the supplied snippet; text updates every 1s.
    if world~=eggScanWorld or now<eggLastScan or now-eggLastScan>=3.0 then
        eggScanWorld=world
        eggLastScan=now
        eggActorsCache=CollectLuckyEggActors(world,now)
    end
    _G.LUCKY_EGG_COUNT.total=#eggActorsCache
    for _,entry in ipairs(eggActorsCache) do
        local egg=entry.actor
        if slua.isValid(egg) then
            local pos
            pcall(function() pos=egg:K2_GetActorLocation() end)
            if pos then
                local dx,dy,dz=pos.X-myPos.X,pos.Y-myPos.Y,pos.Z-myPos.Z
                local distM=math.sqrt(dx*dx+dy*dy+dz*dz)/100.0
                local info=LUCKY_EGG_IDS[entry.id]
                if espOn then
                    -- HUD calls are guarded because their signatures vary by build.
                    pcall(function()
                        hud:AddDebugText(string.format("%s  [%dm]",info.name,math.floor(distM)),
                            egg,1.3,{X=0,Y=0,Z=30},{X=0,Y=0,Z=30},
                            info.color,true,false,true,nil,1.0,true)
                    end)
                end
                if pickOn and distM<=8.0 then
                    local success=pcall(function()
                        if egg.OnPickup then egg:OnPickup(player,0)
                        elseif egg.PickupItem then egg:PickupItem(player)
                        elseif egg.OnInteract then egg:OnInteract(player) end
                    end)
                    if success then
                        _G.LUCKY_EGG_COUNT.picked=(_G.LUCKY_EGG_COUNT.picked or 0)+1
                    end
                end
            end
        end
    end
end

function _G.StartLuckyEgg()
    if (not _G.LUCKY_EGG_ESP_ON and not LuckyEggPickupOn()) or _G.LicenseValid~=true then return false end
    if _G.LUCKY_EGG_TIMER then return true end -- never register duplicates
    local pc=slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
    if not (pc and slua and slua.isValid and slua.isValid(pc) and pc.AddGameTimer) then return false end
    local ok,handle=pcall(function()
        return pc:AddGameTimer(1.0,true,function() pcall(_G.LuckyEggLoop) end)
    end)
    if ok then
        -- Some native builds return nil for a successful repeating timer;
        -- a true sentinel prevents creating an unbounded number of timers.
        _G.LUCKY_EGG_TIMER=handle or true
        eggTimerOwner=pc
        return true
    end
    return false
end

function _G.StopLuckyEgg()
    local handle=_G.LUCKY_EGG_TIMER
    if not handle then return end
    local removed=false
    if handle~=true and eggTimerOwner then
        removed=pcall(function() eggTimerOwner:RemoveGameTimer(handle) end)
    end
    if not removed and handle~=true and _G.Game then
        removed=pcall(function() _G.Game:RemoveGameTimer(handle) end)
    end
    -- A timer without a native removal API stays idle while the switch is OFF;
    -- retain its sentinel so re-enabling never creates duplicate timers.
    _G.LUCKY_EGG_TIMER=(removed and nil or true)
    if removed then eggTimerOwner=nil end
    eggActorsCache={}
    _G.LUCKY_EGG_COUNT.total=0
end

-- Premium Cheats watermark follows only the existing ESP toggles.
-- Aim, Speed, Wall, iPad, Skins and other settings do not trigger it.
local premiumLogoESPKeys={"Name","Line","Box","Health","Distance","Skeleton","Counter"}
_G.SyncPremiumESPLogo = function()
    local active=false
    local esp=_G.g_vipserver_ESPOptions
    if type(esp)=="table" then
        for _,key in ipairs(premiumLogoESPKeys) do
            if esp[key]==true then active=true;break end
        end
    end
    if active then EnsurePermanentDungCu()
    elseif DungCuOverlay.Widget then CleanUpPermanentDungCu() end
end

-- Performance guard: avoid recreating installed UI helpers on every 16 ms tick.
-- Only local scheduling flags; game feature state and online verification remain unchanged.
local proIpadSetupComplete = false
local originalHWIDHelperInstalled = false
local lastESPLogoPollClock = -1e9
-- The original required module is stable once available. Keep retry behavior
-- when absent, but skip repeated protected require calls on every frame.
local cachedMainGameplayData = nil
local function MainLoop()
    if isExpired then return end
    if _G.LicenseValid ~= true then return end
    -- One low-frequency retry only if Egg ESP was enabled before the HUD existed.
    if _G.LUCKY_EGG_ESP_ON and not _G.LUCKY_EGG_TIMER then
        local eggNow=os.clock()
        if eggNow>=eggNextStartAttempt then
            eggNextStartAttempt=eggNow+5.0
            pcall(_G.StartLuckyEgg)
        end
    end
    -- Register settings immediately after a verified login; retry only until
    -- the game's native SettingCatalog and UIManager are available.
    if not _G.ModMenuInitialized and type(_G.InitModMenuTab)=="function" then
        pcall(_G.InitModMenuTab)
    end

    if _G.XthrlenConfig and _G.XthrlenConfig.AimTouchEnable and _G.AimTouch then
        _G.AimTouch()
    end

    -- =====================================================================
    -- HỆ THỐNG LẤY HWID GỐC & ĐỔI HWID ẢO (SPOOFER) CHỐNG BAN
    -- =====================================================================
    if not _G.FakeHWID_Hooked then
    pcall(function()
        local SystemLib = import("KismetSystemLibrary")
        if SystemLib and not _G.FakeHWID_Hooked then
            -- Lưu lại hàm lấy HWID gốc
            _G.Original_GetDeviceId = SystemLib.GetDeviceId

            -- Ghi đè hàm của game
            SystemLib.GetDeviceId = function(...)
                if _G.LexusConfig.FakeHWID then
                    if not _G.FakeHWID_String then
                        -- Tạo ngẫu nhiên một HWID ảo 32 ký tự
                        local chars = "0123456789abcdef"
                        local hwid = ""
                        for i = 1, 32 do 
                            hwid = hwid .. chars:sub(math.random(1, 16), math.random(1, 16)) 
                        end
                        _G.FakeHWID_String = hwid
                    end
                    -- Trả về HWID ảo
                    return _G.FakeHWID_String
                end
                
                -- Nếu tắt Fake HWID thì trả về HWID thật
                if _G.Original_GetDeviceId then return _G.Original_GetDeviceId(...) end
                return "UNKNOWN"
            end
            _G.FakeHWID_Hooked = true
        end
    end)
    end

    -- Hàm độc lập để bạn lấy HWID Gốc (nếu sau này cần hiển thị)
    -- Keep the exact helper function, but do not reallocate it every tick.
    if not originalHWIDHelperInstalled then
    _G.GetOriginalHWID = function()
        if _G.Original_GetDeviceId then
            return tostring(_G.Original_GetDeviceId())
        end
        local SystemLib = import("KismetSystemLibrary")
        if SystemLib and type(SystemLib.GetDeviceId) == "function" then
-- 𝕯𝖚𝖒𝖕_𝖇𝖞_𝕾𝖍𝖆𝖉𝖔𝖜_𝕾𝕳𝕯 SHD_CHT
            return tostring(SystemLib.GetDeviceId())
        end
        return "UNKNOWN_DEVICE"
    end
    originalHWIDHelperInstalled = true
    end

    if _G.LexusState.CustomTextData == nil then
        _G.LexusState.CustomTextData = {IpadViewFOV=120,IpadViewVehicleFOV=120}
    end
    local GameplayData = cachedMainGameplayData
    if not GameplayData then
        local okData, loaded = pcall(require, "GameLua.GameCore.Data.GameplayData")
        if not okData or not loaded then return end
        cachedMainGameplayData = loaded
        GameplayData = loaded
    end
    local pc = GameplayData.GetPlayerController()
    local localPlayer = nil
    if Valid(pc) then localPlayer = pc:GetPlayerCharacterSafety() end
    if not Valid(localPlayer) then
        CleanUpPermanentDungCu()
        return
    end

    -- Same red bottom-left label, visible whenever any enabled menu feature is active.
    local logoPollClock = os.clock()
    if logoPollClock < lastESPLogoPollClock or logoPollClock - lastESPLogoPollClock >= 0.20 then
        lastESPLogoPollClock = logoPollClock
        if type(_G.SyncPremiumESPLogo) == "function" then _G.SyncPremiumESPLogo() end
    end
    -- The welcome UI is one-shot; don't re-evaluate runtime readiness after it.
    if not _G.LexusMenuAlreadyShown and _G.LexusState.MenuStep == 0 then
        ShowLexusVIPMenu()
    end

    -- Original 1.lua Fast Car / Flying Car vehicle acceleration implementation.
    if _G.LexusConfig.FastCar then
        pcall(function()
            local currentVehicle = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
            if Valid(currentVehicle) then
                local rootComp = currentVehicle.RootComponent or (type(currentVehicle.K2_GetRootComponent) == "function" and currentVehicle:K2_GetRootComponent())

                if Valid(rootComp) and type(rootComp.SetAllPhysicsLinearVelocity) == "function" then
                    local isAccelerating = false
                    local moveComp = currentVehicle.VehicleMovement or currentVehicle.MovementComponent
                    if Valid(moveComp) then
                        local throttle = moveComp.ThrottleInput or 0
                        if type(moveComp.GetThrottleInput) == "function" then throttle = moveComp:GetThrottleInput() end
                        if throttle > 0.05 or throttle < -0.05 then isAccelerating = true end
                    end
                    if currentVehicle.bIsPressingGas or (currentVehicle.Throttle and currentVehicle.Throttle ~= 0) then isAccelerating = true end

                    local currentVel = nil
                    if type(currentVehicle.GetVelocity) == "function" then
                        currentVel = currentVehicle:GetVelocity()
                    elseif type(rootComp.GetPhysicsLinearVelocity) == "function" then
                        currentVel = rootComp:GetPhysicsLinearVelocity()
                    elseif rootComp.ComponentVelocity then
                        currentVel = rootComp.ComponentVelocity
                    end

                    if currentVel then
                        local currentSpeed = math.sqrt(currentVel.X ^ 2 + currentVel.Y ^ 2)
                        local minSpeedToBoost = 50.0

                        local maxSpeed = _G.LexusState.CustomTextData.FastCarSpeed or 3000.0

                        local accelFactor = 1.5

                        local brakeFactor = 0.85

                        if currentSpeed > minSpeedToBoost then
                            local dirX = currentVel.X / currentSpeed
-- Ｄｕｍｐ • ｂｙ • Ｓｈａｄｏｗ shadow_cheatss
                            local dirY = currentVel.Y / currentSpeed

                            if isAccelerating then
                                local targetSpeed = currentSpeed * accelFactor
                                if targetSpeed > maxSpeed then targetSpeed = maxSpeed end
                                local newX = dirX * targetSpeed
                                local newY = dirY * targetSpeed
                                local newZ = currentVel.Z
                                rootComp:SetAllPhysicsLinearVelocity(FVector(newX, newY, newZ), false)
                            else
                                local targetSpeed = currentSpeed * brakeFactor
                                if targetSpeed > minSpeedToBoost then
                                    local newX = dirX * targetSpeed
                                    local newY = dirY * targetSpeed
                                    local newZ = currentVel.Z
                                    rootComp:SetAllPhysicsLinearVelocity(FVector(newX, newY, newZ), false)
                                end
                            end
                        end
                    end
                end
            end
        end)
    end


