local function GetPC_Pro()
    local pc = nil
    pcall(function()
        local GD = _G.GameplayData or require("GameLua.GameCore.Data.GameplayData")
        if GD and GD.GetPlayerController then pc = GD.GetPlayerController() end
    end)
    if not slua.isValid(pc) and slua_GameFrontendHUD then
        pcall(function() pc = slua_GameFrontendHUD:GetPlayerController() end)
    end
    return slua.isValid(pc) and pc or nil
end

function _G.ApplyProIpadView()
    if _G.LicenseValid ~= true then return end

    local state = _G.ProIpadView
    local now = os.clock()
    if now - state.LastApply < 0.2 then return end
    state.LastApply = now

    local pc = GetPC_Pro()
    if not slua.isValid(pc) then return end
    local cfg = _G.LexusConfig
    if not cfg then return end

    local char = nil
    pcall(function() char = pc:GetPlayerCharacterSafety() end)
    if not slua.isValid(char) then return end

    -- The earlier version sometimes used controller-wide FOV.  Only clear
    -- such a legacy override outside ADS; touching the controller during
    -- a held scope can make the game repeatedly reopen its scope camera.
    if state.ControllerFOVActive == nil then
        state.ControllerFOVActive = (state.Active == true)
    end

    local inVehicle, isAiming = false, false
    pcall(function()
        inVehicle = slua.isValid(char.CurrentVehicle) or char.bIsInVehicle == true
    end)
    pcall(function()
        local aiming, ads = char.bIsWeaponAiming, char.bIsGunADS
        isAiming = (aiming == true or aiming == 1 or ads == true or ads == 1)
    end)

    -- ADS flags can briefly drop during scope/camera transitions.  Keep
    -- third-person iPad writes paused for a short grace period so one false
    -- ADS read cannot fight the native scope view.
    if isAiming then state.LastADSSeen = now end
    local scopeTransition = state.LastADSSeen ~= nil
        and (now - state.LastADSSeen) < 0.55

    local function resetControllerFOV()
        if not state.ControllerFOVActive then return end
        pcall(function()
            if pc.FOV then pc:FOV(0) end
            local manager = pc.PlayerCameraManager
            if slua.isValid(manager) and type(manager.UnlockFOV) == "function" then
                manager:UnlockFOV()
            end
        end)
        state.ControllerFOVActive = false
        state.LastControllerFOV = nil
        state.LastControllerPC = nil
    end

    local function applyControllerFOV(value)
        -- Vehicle FOV only needs an update when its value or
        -- controller changes; writing every 0.2s can fight native ADS zoom.
        if state.ControllerFOVActive and state.LastControllerFOV == value
            and state.LastControllerPC == pc then return end
        pcall(function()
            if pc.FOV then
                pc:FOV(value)
                state.ControllerFOVActive = true
                state.LastControllerFOV = value
                state.LastControllerPC = pc
            end
        end)
    end

    local data = (_G.LexusState and _G.LexusState.CustomTextData) or {}

    if isAiming then
        -- Normal iPad must never alter controller FOV while scope is held.
        -- Do not reset controller FOV here either: this caused the visible
        -- scope open/close flicker in the previous fix.
        state.Active = state.ControllerFOVActive
        return
    end

    -- In a brief post-ADS transition, neither reset the scope camera nor
    -- change the third-person camera.  Resume only after ADS is stable OFF.
    if scopeTransition then return end

    if inVehicle then
        local vehCam = char.VehicleCameraComponent
        if cfg.IpadViewVehicle then
            local value = data.IpadViewVehicleFOV or 120
            pcall(function()
                if slua.isValid(vehCam) and vehCam.FieldOfView ~= value then
                    vehCam.FieldOfView = value
                end
            end)
            if value > 90 then applyControllerFOV(value)
            else resetControllerFOV() end
            state.Active = true
        else
            resetControllerFOV()
            pcall(function()
                if slua.isValid(vehCam) and vehCam.FieldOfView ~= 90 then
                    vehCam.FieldOfView = 90
                end
            end)
            state.Active = false
        end
        return
    end

    resetControllerFOV()
    local tpp = char.ThirdPersonCameraComponent
    local value = cfg.IpadView and (data.IpadViewFOV or 120) or 90
    pcall(function()
        if slua.isValid(tpp) and tpp.FieldOfView ~= value then
            tpp.FieldOfView = value
        end
    end)
    state.Active = (cfg.IpadView == true)
end
