local cachedFastTickTicker = nil
local function FastTick() 
    if isExpired then 
        if not _G.LexusNotifiedExpire then
            Notify("MOD ĐÃ HẾT HẠN! VUI LÒNG INBOX ADMIN ĐỂ GIA HẠN!\nALL HACK +TOOL AVAILABLE DM OWNER  PREMIUM HACK MAKING COURSE AVAILABLE TELEGRAM  SHADOW")
            _G.LexusNotifiedExpire = true
            ExpiredTick() 
        end
        return 
    end

    -- LICENSE GATE: key verify nahi to loop wait karega, mod dead rahega
    if _G.LicenseValid ~= true then
        if myToken ~= _G.LexusState.LoopToken then return end
        local okT, tkr = pcall(require, "common.time_ticker")
        if okT and tkr and tkr.AddTimerOnce then
            tkr.AddTimerOnce(1.0, FastTick)
        end
        return
    end

    if myToken ~= _G.LexusState.LoopToken then return end
    pcall(MainLoop) 
    local ticker = cachedFastTickTicker
    if not ticker then
        local okTicker, loaded = pcall(require, "common.time_ticker")
        if okTicker and loaded then
            ticker = loaded
            cachedFastTickTicker = loaded
        end
    end
    if ticker and ticker.AddTimerOnce then
        ticker.AddTimerOnce(0.016, FastTick)
    end 
end

